const input = $input.first().json;
const body = input.body || input;

// Validation
const errors = [];

if (!body.query && !body.random) {
  errors.push('Missing required parameter: query (or set random: true)');
}

if (!body.anthropic_api_key && !body.openai_api_key) {
  errors.push('Missing API key: anthropic_api_key or openai_api_key required');
}

if (errors.length > 0) {
  return [{
    json: {
      valid: false,
      error: {
        code: 400,
        message: errors.join(', '),
        status: 'BAD_REQUEST'
      }
    }
  }];
}

// Build prompt based on input type
let prompt = '';
const preferences = body.preferences || {};

if (body.random) {
  const category = preferences.category || 'any';
  prompt = `Generate a random ${category !== 'any' ? category : ''} recipe suggestion. Be creative and surprising.`;
} else if (preferences.must_use_ingredients && preferences.must_use_ingredients.length > 0) {
  const ingredients = preferences.must_use_ingredients.join(', ');
  prompt = `Create a recipe that MUST use these ingredients: ${ingredients}. ${body.query || ''}`;
} else {
  prompt = body.query;
}

// Add preferences to prompt
if (preferences.vegan) prompt += ' The recipe must be vegan.';
if (preferences.vegetarian) prompt += ' The recipe must be vegetarian.';
if (preferences.allergies && preferences.allergies.length > 0) {
  prompt += ` Avoid these allergens: ${preferences.allergies.join(', ')}.`;
}
if (preferences.max_time_minutes) {
  prompt += ` Total time should be under ${preferences.max_time_minutes} minutes.`;
}
if (preferences.difficulty) {
  prompt += ` Difficulty level: ${preferences.difficulty}.`;
}
if (preferences.servings) {
  prompt += ` For ${preferences.servings} servings.`;
}

const language = body.language || 'fr';
const languageMap = { fr: 'French', en: 'English', es: 'Spanish', it: 'Italian' };
prompt += ` Respond in ${languageMap[language] || 'French'}.`;

return [{
  json: {
    valid: true,
    prompt,
    provider: body.anthropic_api_key ? 'anthropic' : 'openai',
    anthropic_api_key: body.anthropic_api_key,
    openai_api_key: body.openai_api_key,
    user_id: body.user_id,
    language,
    original_request: {
      query: body.query,
      random: body.random || false,
      preferences
    }
  }
}];

