const input = $input.first().json;
const prevData = $('Validate Input').first().json;

try {
  if (input.error) {
    return [{
      json: {
        success: false,
        error: {
          code: input.error.status || 500,
          message: input.error.message || 'Anthropic API error',
          status: 'API_ERROR'
        },
        meta: { provider: 'anthropic' }
      }
    }];
  }

  const content = input.content[0].text;
  const recipe = JSON.parse(content);

  return [{
    json: {
      success: true,
      data: {
        recipe,
        source: 'llm_generated',
        original_request: prevData.original_request
      },
      meta: {
        provider: 'anthropic',
        model: input.model || 'claude-sonnet-4-20250514',
        tokens_used: (input.usage?.input_tokens || 0) + (input.usage?.output_tokens || 0),
        usage: input.usage
      }
    }
  }];
} catch (e) {
  return [{
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse recipe: ' + e.message,
        status: 'PARSE_ERROR'
      },
      meta: { provider: 'anthropic' }
    }
  }];
}

